  `kaominina` varchar(255) DEFAULT NULL,
  `distrika` varchar(255) DEFAULT NULL,
  `faritra` varchar(255) DEFAULT NULL,
  `karazan_tany` enum('Titré','Cadastré','Karatany','Taratasin-totra') DEFAULT NULL,
  `titre` varchar(255) NOT NULL,
  `description` text DEFAULT NULL,
  `statut` varchar(100) DEFAULT 'Mavitrika',
  `date_dossier` date DEFAULT NULL,
  `date_creation` timestamp NULL DEFAULT current_timestamp(),
  `date_modification` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_dossier_type` (`type_id`),
  KEY `idx_laharana` (`laharana_fitandremana`),
  KEY `idx_tompony` (`tomponny_tany`),
  KEY `idx_fokontany` (`fokontany`),
  KEY `idx_kaominina` (`kaominina`),
  KEY `idx_distrika` (`distrika`),
  KEY `idx_faritra` (`faritra`),
  CONSTRAINT `fk_dossier_type` FOREIGN KEY (`type_id`) REFERENCES `types_dossiers` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
