DROP TABLE IF EXISTS `lignes_fiara`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `lignes_fiara` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `dossier_id` int(10) unsigned NOT NULL,
  `numero` int(10) unsigned DEFAULT NULL,
  `piece` varchar(255) NOT NULL,
  `cout_remplacement` decimal(15,2) NOT NULL DEFAULT 0.00,
  `cout_reparation` decimal(15,2) NOT NULL DEFAULT 0.00,
  `remarque` text DEFAULT NULL,
  `date_creation` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_lignes_fiara_dossier` (`dossier_id`),
  CONSTRAINT `fk_ligne_fiara_dossier` FOREIGN KEY (`dossier_id`) REFERENCES `dossiers_fiara` (`dossier_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

